    @classmethod
    def _check_rejected_request(
        cls,
        walk: _Walk,
        rides: Sequence[Mapping[str, Any]],
        expectation: Mapping[str, Any],
        seed_time: str,
    ) -> None:
        driver_id = str(expectation.get("driver_id") or DRIVER_ID)
        minimum = int(expectation.get("min_count") or 1)
        matches: list[Mapping[str, Any]] = []
        for ride in rides:
            if driver_id not in [str(value) for value in _rejected_ids(ride)]:
                continue
            if not is_after(_stamp(ride), seed_time):
                continue
            matches.append(ride)
        walk.record(
            "rejected_generated_request",
            passed=len(matches) >= minimum,
            expected=dict(expectation),
            actual={
                "count": len(matches),
                "ride_ids": [_ride_id(ride) for ride in matches][:5],
                "rides": [
                    _present(ride, ("id", "driverId", "status", "createdAt", "rejectedDriverIds"))
                    for ride in matches[:5]
                ],
            },
            failure_reason=(
                "fewer than one post-seed request contains durable rejection evidence for the "
                "driver"
            ),
        )

    @classmethod
    def _check_accepted_trip(
        cls,
        walk: _Walk,
        rides: Sequence[Mapping[str, Any]],
        expectation: Mapping[str, Any],
        seed_time: str,
    ) -> None:
        driver_id = str(expectation.get("driverId") or DRIVER_ID)
        allowed = {str(value) for value in (expectation.get("status_in") or [])}
        near: list[Mapping[str, Any]] = []
        matches: list[Mapping[str, Any]] = []
        for ride in rides:
            if str(_field_value(ride, "driverId") or "") != driver_id:
                continue
            if not is_after(_stamp(ride), seed_time):
                continue
            near.append(ride)
            if expectation.get("require_accepted_at") and not _accepted_stamp(ride):
                continue
            if allowed and str(ride.get("status") or "") not in allowed:
                continue
            matches.append(ride)
        observed = [
            _present(
                ride,
                ("id", "driverId", "status", "createdAt", "acceptedAt", "rejectedDriverIds", "timeline"),
            )
            for ride in (matches or near)[-5:]
        ]
        walk.record(
            "accepted_generated_trip",
            passed=bool(matches),
            expected=dict(expectation),
            actual={
                "match_count": len(matches),
                "ride_ids": [_ride_id(ride) for ride in matches][:5],
                "trips": observed,
            },
            failure_reason=(
                "no post-seed trip contains durable acceptance evidence for the primary driver"
            ),
        )

    @classmethod
    def _check_logout(
        cls,
        walk: _Walk,
        sessions: Sequence[Mapping[str, Any]],
        expectation: Mapping[str, Any],
        driver_id: str,
    ) -> None:
        expected_user = str(expectation.get("userId") or "").strip()
        active: list[Mapping[str, Any]] = []
        for session in sessions:
            session_user = str(session.get("userId") or "")
            if expected_user and session_user != expected_user:
                continue
            if session_user and session_user != driver_id:
                continue
            if _session_is_active(session):
                active.append(session)
        allowed = int(expectation.get("active_sessions") or 0)
        walk.record(
            "final_logout",
            passed=len(active) <= allowed,
            expected=dict(expectation),
            actual={
                "active_sessions": [
                    _present(session, ("id", "userId", "createdAt", "endedAt", "loggedOutAt"))
                    for session in active
                ],
                "session_count": len(sessions),
            },
            failure_reason=(
                "a backend session remains for the driver after the final logout"
            ),
        )

